arguments.command:
cd /workspace && timeout 900 python3 -B -c "
import sys; sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import t1
fails=[]
for seed in range(4000):
    try:
        r=t1.run(seed)
    except Exception as e:
        sys.stderr.write('seed %d EXC %s %s\n'%(seed,type(e).__name__,e)); fails.append(seed); r=None
        if len(fails)>6: break
        continue
    if not r:
        sys.stderr.write('seed %d FAIL\n'%seed); fails.append(seed)
        if len(fails)>6: break
sys.stderr.write('fails %r\n'%(fails,))
" 2>&1 >/dev/null | tail -12
